 leaf:svg('<path d="M52 8C18 5 3 32 19 45 35 57 58 38 52 8" fill="#72ad59" stroke="#467b3c" stroke-width="3"/><path d="M13 57L44 19M25 40L24 25M32 32l13 1" fill="none" stroke="#e1eeb8" stroke-width="3"/>'),
 star:svg('<path d="M32 5l8 18 20 3-15 14 4 20-17-10-18 10 4-20L3 26l21-3z" fill="#ffd15c" stroke="#b78035" stroke-width="3"/>'),
