  if(!particles.some(p=>p.damageActorId&&p.type==='number'&&p.life>0&&p.mesh.parent===this.game.world.effects&&(p.mesh.visible||hidden.has(p)))){if(layer.canvas?.hidden===false)this.clearDamageNumberLayer();return layer.drawn;}
