  const notices=this.nativeLicenses;if(this.game.nativeMode&&this.game.nativeInputBlocked&&notices?.pending){this.cancelNativeLicenses(false);notices.status='error';notices.refresh=true;}
  const screen=this.game.screen,previous=this.focusScreen,modal=this.isModalScreen(screen),ready=this.inputReady===true&&!this.game.nativeInputBlocked&&!this.game.nativeCriticalPending;this.focusScreen=screen;
