    target.focus({preventScroll:true});const bounds=target.getBoundingClientRect(),clip=(panel??this.screens).getBoundingClientRect();if(bounds.top<clip.top||bounds.bottom>clip.bottom||bounds.left<clip.left||bounds.right>clip.right)target.scrollIntoView({block:'nearest',inline:'nearest'});
